    /*카드유효년월     */
    strncpy(zapamcom10070_io.in.card_eff_ym, INPUT->card_eff_ym, LEN_ZAPAMCOM10070_IN_CARD_EFF_YM );
    /*해외카드여부     */
    strncpy(zapamcom10070_io.in.forgn_card_yn, "N", LEN_ZAPAMCOM10070_IN_FORGN_CARD_YN );
    /*예금주관계코드   */
    strncpy(zapamcom10070_io.in.dpstr_rel_cd, "010", LEN_ZAPAMCOM10070_IN_DPSTR_REL_CD );
