    /*계좌인쇄여부     */
    strncpy(zapamcom10070_io.in.bank_prt_yn, INPUT->bank_prt_yn, LEN_ZAPAMCOM10070_IN_BANK_PRT_YN );
    /*주민번호확인여부 */

    strncpy(zapamcom10070_io.in.ctz_num_check_yn, "Y", LEN_ZAPAMCOM10070_IN_CTZ_NUM_CHECK_YN);
    /*최초신청일자   */
    strncpy(zapamcom10070_io.in.fst_req_dt, ctx->gc_get_date, LEN_ZAPAMCOM10070_IN_FST_REQ_DT );
    /*수수료반영여부          */
