             if (strncmp(ctx->gc_rltm_auth_rslt_aply_yn, "Y", LEN_RLTM_AUTH_RSLT_APLY_YN ) == RC_NRM)
             {
                 /* ------------------------------------------------------------------------
                   * 2008/08/11 : 처리결과 정상인 경우 처리상태코드(op_st_cd) = 'Y'로 설정.
