             else
             {
                 /*인증결과코드           */
                 strncpy(zapamcom10070_io.in.auth_rslt_cd, INPUT->eai_gw_rsp_cd, LEN_ZAPAMCOM10070_IN_AUTH_RSLT_CD );
                 /*자동납부신청결과코드    */
                 strncpy(zapamcom10070_io.in.auto_pay_req_rslt_cd , INPUT->eai_gw_rsp_cd, LEN_ZAPAMCOM10070_IN_AUTO_PAY_REQ_RSLT_CD    );
